import {defaultRules,checkFormatting,validateRules} from './format-model.mjs';
import {parseDocx,applyDocx,exampleDocx} from './assets/format-document.js';
import {keys,list,projects,write,recordTask} from './state.mjs';
import {esc,icon,download} from './ui.mjs';
let root,ctx,item,doc,bytes,rules,checked=false,applied=null,dirty=false,busy=false,controller,view='original',tab='base',focus=0;
const $=s=>root.querySelector(s),to64=b=>{let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.slice(i,i+8192));return btoa(s);},from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export const formatHasWork=()=>!!root?.querySelector('.format-space')&&(dirty||busy);
export function formatRouteGuard(){if(!root?.querySelector('.format-space'))return true;if(busy){ctx.notify('文档处理中，请稍候。');return false;}if(dirty&&!confirm('有未保存的排版设置，确定离开？原始文件不会被修改。'))return false;dirty=false;return true;}
window.addEventListener('beforeunload',e=>{if(formatHasWork()){e.preventDefault();e.returnValue='';}});
export async function mountFormat(context,id,projectId){controller?.abort();controller=new AbortController();ctx=context;root=document.querySelector('.dashboard');item=list(keys.drafts).find(d=>String(d.id)===String(id)&&d.tool==='format')||{title:'毕业论文示例',projectId:projectId||'',example:true};rules={...defaultRules(),...item.formatting?.rules};checked=false;applied=null;dirty=false;busy=true;view='original';tab='base';focus=0;root.innerHTML='<div class="format-space"><h1>格式排版</h1><p>正在读取本地文档…</p></div>';try{bytes=item.formatting?.original?from64(item.formatting.original):await exampleDocx();doc=await parseDocx(bytes);if(item.formatting?.levels)doc.paragraphs.forEach((p,i)=>{const l=item.formatting.levels[i];if([0,1,2,3].includes(l))p.level=l;});if(id&&!item.formatting){ctx.notify('旧记录未包含原文文件，请重新上传 DOCX。原记录未被修改。');item={title:'毕业论文示例',example:true,projectId:item.projectId||''};}if(item.formatting?.applied){applied=await applyDocx(bytes,doc,rules);checked=true;view='formatted';}draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('change',changes,{signal:controller.signal});root.addEventListener('input',changes,{signal:controller.signal});}catch(e){root.innerHTML='<div class="format-space"><h1>文档读取失败</h1><p>'+esc(e.message)+'</p><a href="#category/format">重新开始</a></div>';}finally{busy=false;}}
function select(key,label,values){return `<label>${label}<select data-rule="${key}" aria-label="${label}">${values.map(([v,t])=>`<option value="${v}" ${String(rules[key])===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;}
const sizes=[[10.5,'五号 · 10.5pt'],[12,'小四 · 12pt'],[14,'四号 · 14pt'],[16,'三号 · 16pt'],[18,'小二 · 18pt']];
function draw(){const issues=checked?checkFormatting(doc,rules):[],fix=issues.filter(i=>i.status==='fix').length,unknown=issues.length-fix;root.innerHTML=`<div class="format-space"><div class="hub-heading"><div><h1>格式排版</h1><p>上传 DOCX，按规范检查与整理文档格式。</p></div><div class="research-actions"><a class="btn secondary" href="#assets">排版记录</a><label class="btn primary format-upload">${icon('upload',17)}上传论文<input id="format-file" type="file" accept=".docx" aria-label="上传 DOCX 论文"></label></div></div><div class="format-steps">${['上传文档','选择规范','检查与预览','导出文档'].map((s,i)=>`<span class="${i===(applied?3:checked?2:1)?'active':''}"><b>${i+1}</b>${s}</span>`).join('')}</div><div class="format-grid"><section class="card format-settings"><div class="hub-card-heading"><h2>排版规范</h2><span class="hub-badge">${item.example?'示例文档':'用户文档'}</span></div><div class="format-file">${icon('file',25)}<div><b>${esc(item.fileName||item.title+'.docx')}</b><small>${doc.paragraphs.length} 个正文段落 · ${doc.chars} 字符</small></div><button class="text-btn" data-action="original">下载原件</button></div><label class="research-field">成果名称<input id="format-title" aria-label="成果名称" maxlength="120" value="${esc(item.title)}"></label><label class="research-field">所属项目<select id="format-project" aria-label="所属项目"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${item.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="research-field">选择模板<select id="format-template" aria-label="选择模板"><option value="custom">自定义当前规则</option><option value="undergraduate">本科论文通用模板</option><option value="graduate">研究论文通用模板</option></select></label><p class="hub-footnote">通用规则并非学校或期刊官方模板，请核对实际要求。纸张与页眉页码保留原文件设置。</p><div class="research-tabs">${[['base','基础设置'],['heading','标题设置'],['scope','应用范围']].map(([v,t])=>`<button data-tab="${v}" class="${tab===v?'active':''}">${t}</button>`).join('')}</div><div class="format-rule-grid">${tab==='base'?`${select('font','正文字体',['宋体','黑体','仿宋','Times New Roman'].map(v=>[v,v]))}${select('size','正文字号',sizes)}${select('line','行距',[[1,'单倍'],[1.25,'1.25 倍'],[1.5,'1.5 倍'],[2,'2 倍']])}${select('indent','首行缩进',[[0,'无缩进'],[2,'2 字符']])}${['top','bottom','left','right'].map((k,i)=>`<label>${['上','下','左','右'][i]}页边距（cm）<input type="number" min="1" max="5" step="0.1" data-rule="${k}" aria-label="${['上','下','左','右'][i]}页边距" value="${rules[k]}"></label>`).join('')}`:tab==='heading'?`${[1,2,3].map(n=>select('h'+n,n+' 级标题字号',sizes)).join('')}<p class="hub-footnote">标题统一黑体。依据原有大纲级别或“第一章”“1.1 标题”等文本识别，可在右侧手动校正。</p>`:`${[['body','正文样式'],['headings','标题字体与层级'],['margins','所有分节页边距']].map(([k,t])=>`<label class="research-check"><input type="checkbox" data-rule="${k}" ${rules[k]?'checked':''}>${t}</label>`).join('')}<p class="hub-footnote">仅处理正文顶层段落。表格内部、页眉页脚、批注与公式不自动排版。</p>`}</div><div class="research-actions"><button class="btn secondary" data-action="check">检查格式</button><button class="btn primary" data-action="apply" ${doc.blocked?'disabled':''}>应用选定修改</button></div><p id="format-status" class="hub-footnote" role="status">${dirty?'有未保存修改。':applied?'已应用排版，可导出 Word。':'原始文件保留，应用前请核对范围。'}</p><button class="btn secondary" data-action="example">使用示例</button><div class="format-warnings">${doc.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}<p>连续预览仅展示正文文本；图片、表格、公式及真实分页请在 Word 中核对。</p></div></section><div><section class="card format-preview"><div class="hub-card-heading"><h2>文档预览</h2><small>连续预览 · 非 Word 分页</small></div><div class="format-preview-toolbar"><div class="research-tabs">${[['original','原始文档'],['formatted','排版预览']].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}" ${v==='formatted'&&!applied?'disabled':''}>${t}</button>`).join('')}</div><label>定位段落<select id="format-focus" aria-label="定位段落">${doc.paragraphs.map((p,i)=>`<option value="${i}" ${focus===i?'selected':''}>${i+1}. ${esc(p.text.slice(0,18))}</option>`).join('')}</select></label></div><div class="format-paper-wrap"><article class="format-paper" style="padding:${previewMargins()}">${doc.paragraphs.map((p,i)=>paragraph(p,i)).join('')}</article></div></section><section class="card format-results"><div class="hub-card-heading"><h2>格式检查结果</h2><span class="hub-badge">${checked?`${fix} 项可修正 · ${unknown} 项待确认`:'尚未检查'}</span></div>${checked?`<p class="hub-footnote">${applied?'原件检查结果保留，修改清单可供对照。':'检查原件与当前规则；不能确定的格式不会当作已验证合格。'}</p><div class="format-issues">${issues.map((issue,i)=>`<div class="format-issue"><div><b>${issue.index!=null?'段落 '+(issue.index+1):'分节 '+(issue.section+1)} · ${issue.label}</b><p>${esc(issue.current)} → ${esc(issue.target)}</p></div><span class="hub-badge ${issue.status==='unknown'?'gray':''}">${issue.status==='unknown'?'需确认':'可修正'}</span>${issue.index!=null?`<button class="text-btn" data-locate="${issue.index}">查看位置</button>`:''}</div>`).join('')||'<p class="hub-footnote">当前检查范围内未发现差异。复杂对象不在自动检查范围内。</p>'}</div>`:'<div class="research-empty"><p>选择规则后点击“检查格式”，查看实际文档差异。</p></div>'}</section><div class="format-footer"><span>原始文件保留 · 修改可核对</span><div class="research-actions"><button class="btn secondary" data-action="log" ${!applied?'disabled':''}>修改清单</button><button class="btn secondary" data-action="save">保存记录</button><button class="btn primary" data-action="export" ${!applied?'disabled':''}>导出排版 Word</button></div></div></div></div><p class="hub-footnote">当前为本地排版，不上传文档。DOCX 最大 2MB；保存包括原件，浏览器空间不足时请先下载文件。目录、参考文献规范与页码不会自动重建。</p></div>`;bindDrop();}
function previewMargins(){const m=view==='formatted'&&applied&&rules.margins?rules:doc.sections[0]||{};return ['top','right','bottom','left'].map(k=>Math.max(12,Number(m[k]||2.5)*14)+'px').join(' ');}
function paragraph(p,i){const f=p.format,formatted=view==='formatted'&&applied,head=p.level>0,selected=formatted&&(head?rules.headings:rules.body),font=selected?(head?'黑体':rules.font):f.font?.[0]||'宋体',size=selected?Number(head?rules['h'+Math.min(p.level,3)]:rules.size):f.size?.[0]||12,line=selected&&!head?rules.line:f.line?.[0]||1.5,indent=selected&&!head?rules.indent:f.indent?.[0]||0;return `<section id="format-p-${i}" class="format-paragraph ${focus===i?'focused':''}"><p style="font-family:${esc(/^[\p{L}\p{N} -]{1,60}$/u.test(font)?font:'宋体')};font-size:${Math.max(6,Math.min(36,Number(size)||12))}pt;line-height:${Math.max(1,Math.min(3,Number(line)||1.5))};text-indent:${Math.max(0,Math.min(5,Number(indent)||0))}em">${esc(p.text)}</p><label class="format-role">段落 ${i+1}<select data-level="${i}" aria-label="段落 ${i+1} 类型">${[[0,'正文'],[1,'一级标题'],[2,'二级标题'],[3,'三级标题']].map(([v,t])=>`<option value="${v}" ${p.level===v?'selected':''}>${t}</option>`).join('')}</select></label></section>`;}
function invalidate(){checked=false;applied=null;view='original';dirty=true;}
function changes(e){const t=e.target;if(e.type==='input'&&['format-file','format-template'].includes(t.id))return;if(t.id==='format-file'){readFile(t.files[0]);return;}if(t.dataset.rule){rules[t.dataset.rule]=t.type==='checkbox'?t.checked:t.tagName==='SELECT'&&t.dataset.rule==='font'?t.value:Number(t.value);invalidate();$('#format-status').textContent='规则已修改，请重新检查并应用。';root.querySelector('[data-action="export"]').disabled=true;root.querySelector('[data-action="log"]').disabled=true;root.querySelector('[data-view="formatted"]').disabled=true;root.querySelector('.format-paper').style.padding=previewMargins();root.querySelector('.format-paper').innerHTML=doc.paragraphs.map((p,i)=>paragraph(p,i)).join('');root.querySelector('[data-view="original"]').classList.add('active');root.querySelector('[data-view="formatted"]').classList.remove('active');root.querySelector('.format-results').innerHTML='<h2>格式检查结果</h2><p class="hub-footnote">规则已改变，请重新检查。</p>';}else if(t.id==='format-template'){if(t.value==='custom')return;if(!confirm('替换当前排版规则？'))return;rules=defaultRules();if(t.value==='graduate'){rules.line=2;rules.left=3;}invalidate();draw();}else if(t.id==='format-project'){item.projectId=t.value;dirty=true;}else if(t.id==='format-title'){item.title=t.value;dirty=true;}else if(t.dataset.level){doc.paragraphs[Number(t.dataset.level)].level=Number(t.value);invalidate();draw();}else if(t.id==='format-focus'){focus=Number(t.value);locate();}}
function locate(){const target=$('#format-p-'+focus);root.querySelectorAll('.format-paragraph').forEach(p=>p.classList.toggle('focused',p===target));target?.scrollIntoView({block:'nearest',behavior:'smooth'});}
function freeze(value){root.querySelectorAll('button,input,select').forEach(e=>{if(value){e.dataset.previousDisabled=String(e.disabled);e.disabled=true;}else if(e.dataset.previousDisabled!=null){e.disabled=e.dataset.previousDisabled==='true';delete e.dataset.previousDisabled;}});}
async function readFile(file){if(!file||busy)return;if(!/\.docx$/i.test(file.name)||file.size>2*1024*1024)return ctx.notify('请选择 2MB 以内的 DOCX 文件；PDF 不支持原样排版。');busy=true;freeze(true);try{const next=new Uint8Array(await file.arrayBuffer()),parsed=await parseDocx(next);if(dirty&&!confirm('替换当前文档？建议先保存记录或下载文件。'))return;bytes=next;doc=parsed;item={title:file.name.replace(/\.docx$/i,'').slice(0,120),fileName:file.name,projectId:item.projectId||'',example:false};invalidate();focus=0;draw();ctx.notify('已读取原件。复杂对象的保留范围请查看提示。');}catch(e){ctx.notify(e.message||'读取失败，原文档未替换。');}finally{busy=false;freeze(false);}}
function bindDrop(){const zone=$('.format-file');zone.addEventListener('dragover',e=>e.preventDefault());zone.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length===1)readFile(e.dataTransfer.files[0]);else ctx.notify('每次请选择一个文件。');});}
function changeLog(){return {title:item.title,example:item.example,rules,scope:'正文顶层段落及选择的分节页边距',paragraphs:doc.paragraphs.filter(p=>p.level?rules.headings:rules.body).map(p=>({paragraph:p.sourceIndex+1,type:p.level?'标题 '+p.level:'正文'})),originalIssues:checkFormatting(doc,rules),warnings:doc.warnings,note:'未自动修改表格、公式、图片、页眉页脚、批注或目录。'};}
async function actions(e){const b=e.target.closest('button');if(!b||busy)return;try{if(b.dataset.tab){tab=b.dataset.tab;draw();return;}if(b.dataset.view){view=b.dataset.view;draw();return;}if(b.dataset.locate!=null){focus=Number(b.dataset.locate);locate();return;}switch(b.dataset.action){case 'check':validateRules(rules);checked=true;draw();break;case 'apply':validateRules(rules);busy=true;freeze(true);try{applied=await applyDocx(bytes,doc,rules);checked=true;dirty=true;view='formatted';draw();ctx.notify('已生成排版副本，原文件未修改。');}finally{busy=false;freeze(false);}break;case 'original':download(item.fileName||item.title+'-原件.docx',bytes,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');break;case 'export':if(!applied)throw new Error('请先应用修改。');download(item.title+'-排版.docx',applied,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');ctx.notify('已导出 DOCX，请在 Word 中核对最终分页。');break;case 'log':download(item.title+'-修改清单.json',JSON.stringify(changeLog(),null,2),'application/json');break;case 'save':validateRules(rules);if(!item.title.trim())throw new Error('请填写成果名称。');const all=list(keys.drafts),old=all.find(d=>d.id===item.id),now=new Date().toISOString();item={...item,id:item.id||crypto.randomUUID(),tool:'format',stage:'formatted',text:doc.paragraphs.map(p=>p.text).join('\n\n'),createdAt:old?.createdAt||now,updatedAt:now,formatting:{original:to64(bytes),rules,applied:!!applied,levels:doc.paragraphs.map(p=>p.level)}};try{write(keys.drafts,old?all.map(d=>d.id===item.id?item:d):[item,...all]);}catch{throw new Error('浏览器空间不足，记录未保存，请先下载原件和排版文件。');}dirty=false;try{recordTask({id:'draft-'+item.id,title:item.title,kind:'排版记录保存',status:'completed',projectId:item.projectId,url:'#draft/'+item.id});}catch{}draw();ctx.notify('排版记录与原件已保存到当前浏览器。');break;case 'example':if(dirty&&!confirm('放弃未保存修改并打开示例？'))return;busy=true;freeze(true);try{bytes=await exampleDocx();doc=await parseDocx(bytes);item={title:'毕业论文示例',example:true,projectId:''};rules=defaultRules();checked=false;applied=null;dirty=false;view='original';focus=0;draw();}finally{busy=false;freeze(false);}break;}}catch(err){ctx.notify(err.message||'操作失败，请先下载文件。');}}
